515	function buildQuoteMask(text: string): boolean[] {
516		const mask = new Array<boolean>(text.length).fill(false);
517		let index = 0;
518		while (index < text.length) {
519			const closer = QUOTE_PAIRS[text[index] ?? ""];
520			const close = closer === undefined ? -1 : text.indexOf(closer, index + 1);
521			if (close === -1) {
522				index += 1;
523				continue;
524			}
525			for (let position = index; position <= close; position += 1) mask[position] = true;
526			index = close + 1;
527		}
528		return mask;
529	}
