531	function collectProseWarnings(
532		prose: string,
533		quoteMask: boolean[],
534		command: AgentCommandName,
535	): string[] {
536		const tokens: { text: string; index: number }[] = [];
537		const pattern = /\S+/g;
538		for (let match = pattern.exec(prose); match !== null; match = pattern.exec(prose)) {
539			tokens.push({ text: match[0], index: match.index });
540		}
541		const firstToken = tokens[0];
542		const firstProseWord = quoteMask[firstToken.index]
543			? firstToken.text
544			: unescapeWord(firstToken.text);
545		const warnings: string[] = [];
546		for (let index = 0; index < tokens.length; index += 1) {
547			const token = tokens[index];
548			if (quoteMask[token.index]) continue;
549			const option = OPTION_BY_NAME.get(token.text);
550			if (!option) continue;
551			const value = option.arity === "value" ? tokens[index + 1]?.text : undefined;
552			const optionWithValue = value === undefined ? token.text : `${token.text} ${value}`;
553			warnings.push(
554				`${optionWithValue} was included in the prompt body. To specify an argument or an option, place it at the beginning of the command input: /${command} ${optionWithValue} ${firstProseWord} …`,
555			);
556		}
557		return warnings;
558	}
